import { useState, type ChangeEvent } from 'react';
import { Button, Card, Input, Stack, Stepper, Text } from '@jinx-ui/react';

export type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationData) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  city: '',
  street: '',
  zip: '',
};

const REVIEW_FIELDS: Array<{ key: keyof RegistrationData; label: string }> = [
  { key: 'name', label: 'Имя' },
  { key: 'email', label: 'E-mail' },
  { key: 'phone', label: 'Телефон' },
  { key: 'city', label: 'Город' },
  { key: 'street', label: 'Улица, дом' },
  { key: 'zip', label: 'Индекс' },
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(EMPTY);

  const bind = (key: keyof RegistrationData) => ({
    value: data[key],
    onChange: (event: ChangeEvent<HTMLInputElement>) =>
      setData((prev) => ({ ...prev, [key]: event.target.value })),
  });

  const isFirst = step === 0;
  const isLast = step === STEPS.length - 1;

  const goBack = () => setStep((current) => Math.max(0, current - 1));
  const goNext = () => setStep((current) => Math.min(STEPS.length - 1, current + 1));

  return (
    <Card padding="lg" style={{ maxWidth: 'var(--jx-size-form-max, 480px)' }}>
      <Stack direction="column" gap="lg">
        <Stepper activeStep={step}>
          {STEPS.map((label, index) => (
            <Stepper.Step key={label} index={index} label={label} />
          ))}
        </Stepper>

        {step === 0 && (
          <Stack direction="column" gap="md">
            <Input label="Имя" name="name" autoComplete="name" {...bind('name')} />
            <Input label="E-mail" name="email" type="email" autoComplete="email" {...bind('email')} />
            <Input label="Телефон" name="phone" type="tel" autoComplete="tel" {...bind('phone')} />
          </Stack>
        )}

        {step === 1 && (
          <Stack direction="column" gap="md">
            <Input label="Город" name="city" autoComplete="address-level2" {...bind('city')} />
            <Input label="Улица, дом" name="street" autoComplete="street-address" {...bind('street')} />
            <Input label="Индекс" name="zip" autoComplete="postal-code" {...bind('zip')} />
          </Stack>
        )}

        {step === 2 && (
          <Stack direction="column" gap="sm">
            {REVIEW_FIELDS.map(({ key, label }) => (
              <Stack key={key} direction="row" justify="space-between" gap="md">
                <Text tone="muted">{label}</Text>
                <Text>{data[key] || '—'}</Text>
              </Stack>
            ))}
          </Stack>
        )}

        <Stack direction="row" justify="space-between" gap="md">
          <Button type="button" variant="secondary" disabled={isFirst} onClick={goBack}>
            Назад
          </Button>
          {isLast ? (
            <Button type="button" variant="primary" onClick={() => onSubmit(data)}>
              Отправить
            </Button>
          ) : (
            <Button type="button" variant="primary" onClick={goNext}>
              Дальше
            </Button>
          )}
        </Stack>
      </Stack>
    </Card>
  );
}

